// ---- registry: timelocked changes ----

fn propose_e(c: &mut HanaSigner) -> u64 {
    ctx(ALICE, NOW_MS);
    c.propose_change("s1".into(), OwnerAuth::Near, add(E), Some(tok("cp_e_s1_0")))
}

#[test]
fn add_client_after_the_timelock() {
    let mut c = setup();
    let id = propose_e(&mut c);
    assert_eq!(id, 0);
    let ev = events();
    assert_eq!(ev[0]["event"], "change_proposed");
    assert_eq!(ev[0]["data"][0]["by"], serde_json::json!({"Near":{"account_id":ALICE}}));
    assert_eq!(ev[0]["data"][0]["unlock_at_ms"], NOW_MS + DELAY_MS);
    let s1 = c.get_scope("s1".into()).unwrap();
    assert_eq!(s1.pending, vec![PendingChange { id: 0, change: add(E), unlock_at_ms: NOW_MS + DELAY_MS }]);
    assert_eq!(s1.action_nonce, 1);
    assert_eq!(c.scope_for_client("google".into(), E.into()), None);

    ctx(MALLORY, NOW_MS + DELAY_MS); // anyone may execute
    c.execute_change("s1".into(), 0);
    assert_eq!(events()[0]["event"], "change_executed");
    assert_eq!(c.scope_for_client("google".into(), E.into()), Some("s1".into()));
    let s1 = c.get_scope("s1".into()).unwrap();
    assert!(s1.pending.is_empty());
    assert_eq!(s1.clients.len(), 3);

    // E's users now land in s1, with the same keys as A's users.
    let s = c.create_session(tok("session_e_late"), "s1".into(), pk(7), EXPIRES_LATE_MS, SALT.to_vec(), 0, 3);
    assert_eq!(s.path, format!("s1#google#{USER}#0"));
}

