/// Pads s1 (clients [A, A2]) with made-up clients up to `count`.
fn fill_s1(c: &mut HanaSigner, count: usize) {
    let mut s1 = c.get_scope("s1".into()).unwrap();
    for i in s1.clients.len()..count {
        let client = google(&format!("filler-{i}.apps.googleusercontent.com"));
        c.client_index.insert(client.clone(), "s1".into());
        s1.clients.push(client);
    }
    c.scopes.insert("s1".into(), s1);
}

